SET SQL_MODE = "NO_AUTO_VALUE_ON_ZERO"; SET AUTOCOMMIT = 0; START TRANSACTION; SET time_zone = "+06:00";  -- ------------------------------------------------------------ --  CREATE DATABASE -- ------------------------------------------------------------ CREATE DATABASE IF NOT EXISTS `unibites`   DEFAULT CHARACTER SET utf8mb4   COLLATE utf8mb4_unicode_ci;  USE `unibites`;  -- ============================================================ --  TABLE: users -- ============================================================ DROP TABLE IF EXISTS `users`; CREATE TABLE `users` (   `id`               INT(11)       NOT NULL AUTO_INCREMENT,   `first_name`       VARCHAR(50)   NOT NULL,   `last_name`        VARCHAR(50)   NOT NULL,   `email`            VARCHAR(100)  NOT NULL,   `password`         VARCHAR(255)  NOT NULL COMMENT 'bcrypt hashed',   `phone`            VARCHAR(20)   DEFAULT NULL,   `university_id`    VARCHAR(30)   DEFAULT NULL,   `department`       VARCHAR(100)  DEFAULT NULL,   `profile_photo`    VARCHAR(255)  DEFAULT 'default.png',   `default_location` TEXT          DEFAULT NULL,   `balance`          DECIMAL(10,2) NOT NULL DEFAULT 0.00,   `total_earnings`   DECIMAL(10,2) NOT NULL DEFAULT 0.00,   `role`             ENUM('user','admin') NOT NULL DEFAULT 'user',   `is_rider`         TINYINT(1)    NOT NULL DEFAULT 0,   `email_verified`   TINYINT(1)    NOT NULL DEFAULT 0,   `is_active`        TINYINT(1)    NOT NULL DEFAULT 1,   `created_at`       TIMESTAMP     NOT NULL DEFAULT CURRENT_TIMESTAMP,   `updated_at`       TIMESTAMP     NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,   PRIMARY KEY (`id`),   UNIQUE KEY `uq_users_email` (`email`),   KEY `idx_users_role`     (`role`),   KEY `idx_users_is_rider` (`is_rider`) ) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;  -- ============================================================ --  TABLE: password_resets -- ============================================================ DROP TABLE IF EXISTS `password_resets`; CREATE TABLE `password_resets` (   `id`         INT(11)      NOT NULL AUTO_INCREMENT,   `user_id`    INT(11)      NOT NULL,   `token`      VARCHAR(255) NOT NULL,   `expires_at` DATETIME     NOT NULL,   `used`       TINYINT(1)   NOT NULL DEFAULT 0,   `created_at` TIMESTAMP    NOT NULL DEFAULT CURRENT_TIMESTAMP,   PRIMARY KEY (`id`),   KEY `idx_pr_user_id` (`user_id`),   KEY `idx_pr_token`   (`token`),   CONSTRAINT `fk_pr_user_id` FOREIGN KEY (`user_id`) REFERENCES `users` (`id`) ON DELETE CASCADE ) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;  -- ============================================================ --  TABLE: stalls -- ============================================================ DROP TABLE IF EXISTS `stalls`; CREATE TABLE `stalls` (   `id`          INT(11)      NOT NULL AUTO_INCREMENT,   `name`        VARCHAR(100) NOT NULL,   `slug`        VARCHAR(100) NOT NULL,   `description` TEXT         DEFAULT NULL,   `location`    VARCHAR(200) DEFAULT NULL,   `image`       VARCHAR(255) DEFAULT 'stall_default.jpg',   `is_active`   TINYINT(1)   NOT NULL DEFAULT 1,   `sort_order`  INT(11)      NOT NULL DEFAULT 0,   `created_at`  TIMESTAMP    NOT NULL DEFAULT CURRENT_TIMESTAMP,   `updated_at`  TIMESTAMP    NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,   PRIMARY KEY (`id`),   UNIQUE KEY `uq_stalls_slug` (`slug`),   KEY `idx_stalls_is_active` (`is_active`) ) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;  -- ============================================================ --  TABLE: categories -- ============================================================ DROP TABLE IF EXISTS `categories`; CREATE TABLE `categories` (   `id`         INT(11)      NOT NULL AUTO_INCREMENT,   `name`       VARCHAR(100) NOT NULL,   `slug`       VARCHAR(100) NOT NULL,   `icon`       VARCHAR(50)  DEFAULT NULL,   `sort_order` INT(11)      NOT NULL DEFAULT 0,   `is_active`  TINYINT(1)   NOT NULL DEFAULT 1,   `created_at` TIMESTAMP    NOT NULL DEFAULT CURRENT_TIMESTAMP,   PRIMARY KEY (`id`),   UNIQUE KEY `uq_categories_slug` (`slug`) ) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;  -- ============================================================ --  TABLE: foods -- ============================================================ DROP TABLE IF EXISTS `foods`; CREATE TABLE `foods` (   `id`           INT(11)       NOT NULL AUTO_INCREMENT,   `stall_id`     INT(11)       NOT NULL,   `category_id`  INT(11)       DEFAULT NULL,   `name`         VARCHAR(100)  NOT NULL,   `description`  TEXT          DEFAULT NULL,   `price`        DECIMAL(10,2) NOT NULL,   `image`        VARCHAR(255)  DEFAULT 'food_default.jpg',   `is_available` TINYINT(1)    NOT NULL DEFAULT 1,   `is_popular`   TINYINT(1)    NOT NULL DEFAULT 0,   `is_special`   TINYINT(1)    NOT NULL DEFAULT 0,   `tag`          VARCHAR(50)   DEFAULT NULL,   `sort_order`   INT(11)       NOT NULL DEFAULT 0,   `created_at`   TIMESTAMP     NOT NULL DEFAULT CURRENT_TIMESTAMP,   `updated_at`   TIMESTAMP     NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,   PRIMARY KEY (`id`),   KEY `idx_foods_stall_id`     (`stall_id`),   KEY `idx_foods_category_id`  (`category_id`),   KEY `idx_foods_is_available` (`is_available`),   KEY `idx_foods_is_popular`   (`is_popular`),   KEY `idx_foods_is_special`   (`is_special`),   CONSTRAINT `fk_foods_stall_id`    FOREIGN KEY (`stall_id`)    REFERENCES `stalls`     (`id`) ON DELETE CASCADE,   CONSTRAINT `fk_foods_category_id` FOREIGN KEY (`category_id`) REFERENCES `categories` (`id`) ON DELETE SET NULL ) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;  -- ============================================================ --  TABLE: orders -- ============================================================ DROP TABLE IF EXISTS `orders`; CREATE TABLE `orders` (   `id`               INT(11)       NOT NULL AUTO_INCREMENT,   `user_id`          INT(11)       NOT NULL,   `order_number`     VARCHAR(20)   NOT NULL,   `full_name`        VARCHAR(100)  NOT NULL,   `phone`            VARCHAR(20)   NOT NULL,   `location`         TEXT          NOT NULL,   `email`            VARCHAR(100)  DEFAULT NULL,   `student_id`       VARCHAR(30)   DEFAULT NULL,   `notes`            TEXT          DEFAULT NULL,   `subtotal`         DECIMAL(10,2) NOT NULL DEFAULT 0.00,   `delivery_fee`     DECIMAL(10,2) NOT NULL DEFAULT 18.00,   `total`            DECIMAL(10,2) NOT NULL DEFAULT 0.00,   `payment_method`   ENUM('cash_on_delivery','online') NOT NULL DEFAULT 'cash_on_delivery',   `payment_status`   ENUM('pending','processing','paid','failed','refunded') NOT NULL DEFAULT 'pending',   `transaction_id`   VARCHAR(100)  DEFAULT NULL,   `delivery_type`    ENUM('pickup','delivery') NOT NULL DEFAULT 'delivery',   `status`           ENUM(                        'pending',                        'confirmed',                        'preparing',                        'ready',                        'delivery_requested',                        'rider_accepted',                        'picked_up',                        'out_for_delivery',                        'delivered',                        'completed',                        'cancelled'                      ) NOT NULL DEFAULT 'pending',   `rider_id`         INT(11)       DEFAULT NULL,   `cancelled_reason` TEXT          DEFAULT NULL,   `created_at`       TIMESTAMP     NOT NULL DEFAULT CURRENT_TIMESTAMP,   `updated_at`       TIMESTAMP     NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,   PRIMARY KEY (`id`),   UNIQUE KEY `uq_orders_order_number` (`order_number`),   KEY `idx_orders_user_id`  (`user_id`),   KEY `idx_orders_status`   (`status`),   KEY `idx_orders_rider_id` (`rider_id`),   KEY `idx_orders_created`  (`created_at`),   CONSTRAINT `fk_orders_user_id`  FOREIGN KEY (`user_id`)  REFERENCES `users` (`id`) ON DELETE RESTRICT,   CONSTRAINT `fk_orders_rider_id` FOREIGN KEY (`rider_id`) REFERENCES `users` (`id`) ON DELETE SET NULL ) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;  -- ============================================================ --  TABLE: order_items -- ============================================================ DROP TABLE IF EXISTS `order_items`; CREATE TABLE `order_items` (   `id`          INT(11)       NOT NULL AUTO_INCREMENT,   `order_id`    INT(11)       NOT NULL,   `food_id`     INT(11)       DEFAULT NULL,   `food_name`   VARCHAR(100)  NOT NULL,   `stall_name`  VARCHAR(100)  NOT NULL,   `quantity`    INT(11)       NOT NULL DEFAULT 1,   `unit_price`  DECIMAL(10,2) NOT NULL,   `total_price` DECIMAL(10,2) NOT NULL,   PRIMARY KEY (`id`),   KEY `idx_oi_order_id` (`order_id`),   KEY `idx_oi_food_id`  (`food_id`),   CONSTRAINT `fk_oi_order_id` FOREIGN KEY (`order_id`) REFERENCES `orders` (`id`) ON DELETE CASCADE,   CONSTRAINT `fk_oi_food_id`  FOREIGN KEY (`food_id`)  REFERENCES `foods`  (`id`) ON DELETE SET NULL ) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;  -- ============================================================ --  TABLE: deliveries --  FIX: accepted_at, picked_up_at, delivered_at → DATETIME --       (avoids #1067 in strict MySQL mode with multiple --        TIMESTAMP columns that are nullable) -- ============================================================ DROP TABLE IF EXISTS `deliveries`; CREATE TABLE `deliveries` (   `id`           INT(11)       NOT NULL AUTO_INCREMENT,   `order_id`     INT(11)       NOT NULL,   `rider_id`     INT(11)       DEFAULT NULL,   `status`       ENUM(                    'pending',                    'accepted',                    'picked_up',                    'out_for_delivery',                    'delivered',                    'cancelled'                  ) NOT NULL DEFAULT 'pending',   `delivery_fee` DECIMAL(10,2) NOT NULL DEFAULT 18.00,   `rider_earn`   DECIMAL(10,2) NOT NULL DEFAULT 12.00 COMMENT 'Rider share of delivery fee',   `accepted_at`  DATETIME      DEFAULT NULL,   `picked_up_at` DATETIME      DEFAULT NULL,   `delivered_at` DATETIME      DEFAULT NULL,   `created_at`   TIMESTAMP     NOT NULL DEFAULT CURRENT_TIMESTAMP,   `updated_at`   TIMESTAMP     NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,   PRIMARY KEY (`id`),   UNIQUE KEY `uq_deliveries_order_id` (`order_id`) COMMENT 'One delivery record per order',   KEY `idx_deliveries_rider_id` (`rider_id`),   KEY `idx_deliveries_status`   (`status`),   CONSTRAINT `fk_deliveries_order_id` FOREIGN KEY (`order_id`) REFERENCES `orders` (`id`) ON DELETE CASCADE,   CONSTRAINT `fk_deliveries_rider_id` FOREIGN KEY (`rider_id`) REFERENCES `users`  (`id`) ON DELETE SET NULL ) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;  -- ============================================================ --  TABLE: payments -- ============================================================ DROP TABLE IF EXISTS `payments`; CREATE TABLE `payments` (   `id`               INT(11)       NOT NULL AUTO_INCREMENT,   `order_id`         INT(11)       NOT NULL,   `user_id`          INT(11)       NOT NULL,   `method`           ENUM('cash_on_delivery','card','bkash','rocket','nagad','online') NOT NULL,   `amount`           DECIMAL(10,2) NOT NULL,   `currency`         VARCHAR(5)    NOT NULL DEFAULT 'BDT',   `status`           ENUM('pending','processing','paid','failed','refunded') NOT NULL DEFAULT 'pending',   `transaction_id`   VARCHAR(100)  DEFAULT NULL,   `gateway_response` TEXT          DEFAULT NULL,   `paid_at`          DATETIME      DEFAULT NULL,   `created_at`       TIMESTAMP     NOT NULL DEFAULT CURRENT_TIMESTAMP,   `updated_at`       TIMESTAMP     NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,   PRIMARY KEY (`id`),   KEY `idx_payments_order_id` (`order_id`),   KEY `idx_payments_user_id`  (`user_id`),   KEY `idx_payments_status`   (`status`),   KEY `idx_payments_method`   (`method`),   CONSTRAINT `fk_payments_order_id` FOREIGN KEY (`order_id`) REFERENCES `orders` (`id`) ON DELETE CASCADE,   CONSTRAINT `fk_payments_user_id`  FOREIGN KEY (`user_id`)  REFERENCES `users`  (`id`) ON DELETE RESTRICT ) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;  -- ============================================================ --  TABLE: reviews -- ============================================================ DROP TABLE IF EXISTS `reviews`; CREATE TABLE `reviews` (   `id`         INT(11)    NOT NULL AUTO_INCREMENT,   `user_id`    INT(11)    NOT NULL,   `food_id`    INT(11)    DEFAULT NULL,   `order_id`   INT(11)    DEFAULT NULL,   `stall_id`   INT(11)    DEFAULT NULL,   `rating`     TINYINT(1) NOT NULL,   `review`     TEXT       DEFAULT NULL,   `is_visible` TINYINT(1) NOT NULL DEFAULT 1,   `created_at` TIMESTAMP  NOT NULL DEFAULT CURRENT_TIMESTAMP,   PRIMARY KEY (`id`),   KEY `idx_reviews_user_id`  (`user_id`),   KEY `idx_reviews_food_id`  (`food_id`),   KEY `idx_reviews_stall_id` (`stall_id`),   KEY `idx_reviews_order_id` (`order_id`),   CONSTRAINT `fk_reviews_user_id`  FOREIGN KEY (`user_id`)  REFERENCES `users`  (`id`) ON DELETE CASCADE,   CONSTRAINT `fk_reviews_food_id`  FOREIGN KEY (`food_id`)  REFERENCES `foods`  (`id`) ON DELETE SET NULL,   CONSTRAINT `fk_reviews_order_id` FOREIGN KEY (`order_id`) REFERENCES `orders` (`id`) ON DELETE SET NULL,   CONSTRAINT `fk_reviews_stall_id` FOREIGN KEY (`stall_id`) REFERENCES `stalls` (`id`) ON DELETE SET NULL ) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;  -- ============================================================ --  TABLE: notifications -- ============================================================ DROP TABLE IF EXISTS `notifications`; CREATE TABLE `notifications` (   `id`         INT(11)      NOT NULL AUTO_INCREMENT,   `user_id`    INT(11)      DEFAULT NULL,   `title`      VARCHAR(150) NOT NULL,   `message`    TEXT         NOT NULL,   `type`       ENUM(                  'order_confirmed','order_preparing','order_ready',                  'rider_accepted','picked_up','out_for_delivery',                  'order_delivered','payment_success','payment_failed',                  'order_cancelled','new_stall','new_food',                  'price_update','special_food','announcement'                ) NOT NULL DEFAULT 'announcement',   `is_read`    TINYINT(1)   NOT NULL DEFAULT 0,   `created_at` TIMESTAMP    NOT NULL DEFAULT CURRENT_TIMESTAMP,   PRIMARY KEY (`id`),   KEY `idx_notif_user_id` (`user_id`),   KEY `idx_notif_is_read` (`is_read`),   KEY `idx_notif_type`    (`type`),   CONSTRAINT `fk_notif_user_id` FOREIGN KEY (`user_id`) REFERENCES `users` (`id`) ON DELETE CASCADE ) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;  -- ============================================================ --  TABLE: favorites -- ============================================================ DROP TABLE IF EXISTS `favorites`; CREATE TABLE `favorites` (   `id`         INT(11)   NOT NULL AUTO_INCREMENT,   `user_id`    INT(11)   NOT NULL,   `food_id`    INT(11)   DEFAULT NULL,   `stall_id`   INT(11)   DEFAULT NULL,   `created_at` TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,   PRIMARY KEY (`id`),   KEY `idx_fav_user_id`  (`user_id`),   KEY `idx_fav_food_id`  (`food_id`),   KEY `idx_fav_stall_id` (`stall_id`),   CONSTRAINT `fk_fav_user_id`  FOREIGN KEY (`user_id`)  REFERENCES `users`  (`id`) ON DELETE CASCADE,   CONSTRAINT `fk_fav_food_id`  FOREIGN KEY (`food_id`)  REFERENCES `foods`  (`id`) ON DELETE CASCADE,   CONSTRAINT `fk_fav_stall_id` FOREIGN KEY (`stall_id`) REFERENCES `stalls` (`id`) ON DELETE CASCADE ) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;  -- ============================================================ --  TABLE: rider_ratings -- ============================================================ DROP TABLE IF EXISTS `rider_ratings`; CREATE TABLE `rider_ratings` (   `id`          INT(11)    NOT NULL AUTO_INCREMENT,   `delivery_id` INT(11)    NOT NULL,   `rider_id`    INT(11)    NOT NULL,   `customer_id` INT(11)    NOT NULL,   `rating`      TINYINT(1) NOT NULL,   `comment`     TEXT       DEFAULT NULL,   `created_at`  TIMESTAMP  NOT NULL DEFAULT CURRENT_TIMESTAMP,   PRIMARY KEY (`id`),   UNIQUE KEY `uq_rr_delivery_id` (`delivery_id`),   KEY `idx_rr_rider_id`    (`rider_id`),   KEY `idx_rr_customer_id` (`customer_id`),   CONSTRAINT `fk_rr_delivery_id` FOREIGN KEY (`delivery_id`) REFERENCES `deliveries` (`id`) ON DELETE CASCADE,   CONSTRAINT `fk_rr_rider_id`    FOREIGN KEY (`rider_id`)    REFERENCES `users`       (`id`) ON DELETE CASCADE,   CONSTRAINT `fk_rr_customer_id` FOREIGN KEY (`customer_id`) REFERENCES `users`       (`id`) ON DELETE CASCADE ) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;  -- ============================================================ --  TABLE: contact_messages -- ============================================================ DROP TABLE IF EXISTS `contact_messages`; CREATE TABLE `contact_messages` (   `id`         INT(11)      NOT NULL AUTO_INCREMENT,   `name`       VARCHAR(100) NOT NULL,   `phone`      VARCHAR(20)  DEFAULT NULL,   `email`      VARCHAR(100) NOT NULL,   `message`    TEXT         NOT NULL,   `is_read`    TINYINT(1)   NOT NULL DEFAULT 0,   `created_at` TIMESTAMP    NOT NULL DEFAULT CURRENT_TIMESTAMP,   PRIMARY KEY (`id`),   KEY `idx_cm_is_read` (`is_read`) ) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;  -- ============================================================ --  TABLE: admin_logs -- ============================================================ DROP TABLE IF EXISTS `admin_logs`; CREATE TABLE `admin_logs` (   `id`         INT(11)      NOT NULL AUTO_INCREMENT,   `admin_id`   INT(11)      NOT NULL,   `action`     VARCHAR(200) NOT NULL,   `table_name` VARCHAR(50)  DEFAULT NULL,   `record_id`  INT(11)      DEFAULT NULL,   `old_value`  TEXT         DEFAULT NULL,   `new_value`  TEXT         DEFAULT NULL,   `ip_address` VARCHAR(45)  DEFAULT NULL,   `created_at` TIMESTAMP    NOT NULL DEFAULT CURRENT_TIMESTAMP,   PRIMARY KEY (`id`),   KEY `idx_al_admin_id`   (`admin_id`),   KEY `idx_al_table_name` (`table_name`),   CONSTRAINT `fk_al_admin_id` FOREIGN KEY (`admin_id`) REFERENCES `users` (`id`) ON DELETE RESTRICT ) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;  -- ============================================================ --  TABLE: sessions -- ============================================================ DROP TABLE IF EXISTS `sessions`; CREATE TABLE `sessions` (   `id`         INT(11)      NOT NULL AUTO_INCREMENT,   `user_id`    INT(11)      NOT NULL,   `token`      VARCHAR(255) NOT NULL,   `ip_address` VARCHAR(45)  DEFAULT NULL,   `user_agent` TEXT         DEFAULT NULL,   `expires_at` DATETIME     NOT NULL,   `created_at` TIMESTAMP    NOT NULL DEFAULT CURRENT_TIMESTAMP,   PRIMARY KEY (`id`),   KEY `idx_sess_user_id` (`user_id`),   KEY `idx_sess_token`   (`token`),   CONSTRAINT `fk_sess_user_id` FOREIGN KEY (`user_id`) REFERENCES `users` (`id`) ON DELETE CASCADE ) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;   -- ============================================================ --  SAMPLE DATA -- ============================================================  -- Users  (password for all = Test@1234) INSERT INTO `users`   (`id`,`first_name`,`last_name`,`email`,`password`,`phone`,`university_id`,`department`,`default_location`,`balance`,`total_earnings`,`role`,`is_rider`,`email_verified`,`is_active`) VALUES   (1,'Admin','UniBites','admin@unibites.com',    '$2y$10$92IXUNpkjO0rOQ5byMi.Ye4oKoEa3Ro9llC/.og/at2.uheWG/igi',    '01811111111',NULL,NULL,NULL,0.00,0.00,'admin',0,1,1),    (2,'New','User','user@bscse.uiu.ac.bd',    '$2y$10$92IXUNpkjO0rOQ5byMi.Ye4oKoEa3Ro9llC/.og/at2.uheWG/igi',    '017xxxxxxx','UIU-2021-001','CSE','Room 530, 9th Floor, UIU',205.00,510.00,'user',1,1,1),    (3,'Farhan','Rahman','farhan@bscse.uiu.ac.bd',    '$2y$10$92IXUNpkjO0rOQ5byMi.Ye4oKoEa3Ro9llC/.og/at2.uheWG/igi',    '018xxxxxxx','UIU-2022-045','CSE','Room 201, 3rd Floor, UIU',0.00,0.00,'user',0,1,1),    (4,'Nadia','Islam','nadia@bscse.uiu.ac.bd',    '$2y$10$92IXUNpkjO0rOQ5byMi.Ye4oKoEa3Ro9llC/.og/at2.uheWG/igi',    '015xxxxxxx','UIU-2023-012','EEE','Lab 401, 4th Floor, UIU',0.00,1200.00,'user',1,1,1),    (5,'Shakib','Hasan','shakib@bscse.uiu.ac.bd',    '$2y$10$92IXUNpkjO0rOQ5byMi.Ye4oKoEa3Ro9llC/.og/at2.uheWG/igi',    '013xxxxxxx','UIU-2021-078','CSE','Room 530, 9th Floor, UIU',0.00,2450.00,'user',1,1,1),    (6,'Mania','Akter','mania@bscse.uiu.ac.bd',    '$2y$10$92IXUNpkjO0rOQ5byMi.Ye4oKoEa3Ro9llC/.og/at2.uheWG/igi',    '016xxxxxxx','UIU-2022-033','CSE',NULL,0.00,1800.00,'user',1,1,1),    (7,'Shakil','Ahmed','shakil@bscse.uiu.ac.bd',    '$2y$10$92IXUNpkjO0rOQ5byMi.Ye4oKoEa3Ro9llC/.og/at2.uheWG/igi',    '019xxxxxxx','UIU-2023-005','BBA',NULL,0.00,960.00,'user',1,1,1);  -- Stalls INSERT INTO `stalls` (`id`,`name`,`slug`,`description`,`location`,`image`,`is_active`,`sort_order`) VALUES   (1,"Khan's Kitchen",'khans-kitchen','Authentic campus flavors — burgers, rolls, wings and more.','Ground Floor, Main Cafeteria, UIU','khans_kitchen.jpg',1,1),   (2,'Olympia','olympia','Hearty lunch platters, rice dishes and heavy meals.','Ground Floor, Main Cafeteria, UIU','olympia.jpg',1,2),   (3,'Well Food','well-food','Fresh bakery, sweets, cakes and ice cream.','Ground Floor, East Wing, UIU','well_food.jpg',1,3),   (4,'CP','cp','Crispy chicken snacks, balls, sausages and fried rice.','Ground Floor, Main Cafeteria, UIU','cp.jpg',1,4),   (5,'Brew Cafe','brew-cafe','Freshly brewed coffees, lattes and refreshing drinks.','Campus Brew Cafe, UIU','brew_cafe.jpg',1,5),   (6,'Cafe Neptune','cafe-neptune','Affordable everyday meals — parata, milk tea, jilapi and more.','Canteen Area, UIU','cafe_neptune.jpg',1,6);  -- Categories INSERT INTO `categories` (`id`,`name`,`slug`,`icon`,`sort_order`,`is_active`) VALUES   (1,'Burger','burger','fa-hamburger',1,1),   (2,'Pizza','pizza','fa-pizza-slice',2,1),   (3,'Chicken','chicken','fa-drumstick-bite',3,1),   (4,'Coffee','coffee','fa-coffee',4,1),   (5,'Drinks','drinks','fa-glass-cheers',5,1),   (6,'Snacks','snacks','fa-cookie',6,1),   (7,'Dessert','dessert','fa-ice-cream',7,1),   (8,'Rice & Meal','rice-meal','fa-bowl-rice',8,1),   (9,'Bread','bread','fa-bread-slice',9,1),   (10,'Fast Food','fast-food','fa-utensils',10,1),   (11,'Cake & Sweet','cake-sweet','fa-birthday-cake',11,1),   (12,'Tea','tea','fa-mug-hot',12,1);  -- Foods — Khan's Kitchen (stall_id=1) INSERT INTO `foods` (`stall_id`,`category_id`,`name`,`description`,`price`,`image`,`is_available`,`is_popular`,`is_special`,`tag`,`sort_order`) VALUES   (1,1,'BBQ Chicken Burger','Juicy patty with BBQ sauce, lettuce and tomato',50.00,'khans_bbq_burger.jpg',1,1,1,NULL,1),   (1,3,'Chicken Roll','Crispy chicken wrapped in paratha with special sauce',40.00,'khans_chicken_roll.jpg',1,1,1,NULL,2),   (1,3,'BBQ Chicken Wings','Smoky BBQ-glazed wings with dipping sauce',55.00,'khans_bbq_wings.jpg',1,0,1,NULL,3),   (1,2,'Slice Pizza','Loaded cheese pizza slice',70.00,'khans_slice_pizza.jpg',1,0,1,NULL,4),   (1,5,'Lassi','Creamy sweet or salted lassi',40.00,'khans_lassi.jpg',1,0,1,NULL,5),   (1,12,'Milk Tea','Freshly brewed milk tea',10.00,'khans_milk_tea.jpg',1,0,0,NULL,6),   (1,9,'Chicken Paratha','Stuffed chicken paratha grilled to perfection',90.00,'khans_paratha.jpg',1,0,0,NULL,7),   (1,3,'Crispy Chicken Fry','Crunchy fried chicken pieces',80.00,'khans_crispy.jpg',1,0,0,NULL,8);  -- Foods — Olympia (stall_id=2) INSERT INTO `foods` (`stall_id`,`category_id`,`name`,`description`,`price`,`image`,`is_available`,`is_popular`,`is_special`,`tag`,`sort_order`) VALUES   (2,1,'BBQ Chicken Burger','Olympia-style smoky BBQ burger',50.00,'olympia_burger.jpg',1,0,1,NULL,1),   (2,5,'Lassi','Chilled sweet lassi',40.00,'olympia_lassi.jpg',1,0,1,NULL,2),   (2,3,'BBQ Chicken Wings','Grilled wings with tangy BBQ glaze',55.00,'olympia_wings.jpg',1,0,1,NULL,3),   (2,2,'Slice Pizza','Cheese-loaded pizza slice',70.00,'olympia_pizza.jpg',1,0,1,NULL,4),   