e_plain_rice.jpg',1,0,1,'270-300gms',4),   (6,8,'Mixed Vegetable','Stir-fried seasonal vegetables',25.00,'neptune_mixed_veg.jpg',1,0,1,NULL,5),   (6,6,'Jilapi','Crispy golden jilapi',10.00,'neptune_jilapi.jpg',1,1,1,NULL,6),   (6,8,'Dal','Freshly cooked mixed dal',20.00,'neptune_dal.jpg',1,0,0,NULL,7),   (6,9,'Roti','Soft whole-wheat roti 2pcs',10.00,'neptune_roti.jpg',1,0,0,NULL,8);  -- Sample Orders INSERT INTO `orders`   (`id`,`user_id`,`order_number`,`full_name`,`phone`,`location`,`email`,`student_id`,`notes`,`subtotal`,`delivery_fee`,`total`,`payment_method`,`payment_status`,`delivery_type`,`status`,`rider_id`,`created_at`) VALUES   (1,3,'012374637','Shakib Hasan','017xxxxxxx','Room 530, 9th Floor, UIU','shakib@bscse.uiu.ac.bd','UIU-2021-078',NULL,175.00,20.00,195.00,'cash_on_delivery','paid','delivery','delivered',2,'2026-08-25 10:45:00'),   (2,3,'012374638','Shakib Hasan','017xxxxxxx','Room 530, 9th Floor, UIU','shakib@bscse.uiu.ac.bd','UIU-2021-078',NULL,175.00,20.00,195.00,'cash_on_delivery','paid','delivery','delivered',2,'2026-08-25 11:00:00'),   (3,3,'012374639','Shakib Hasan','017xxxxxxx','Room 530, 9th Floor, UIU','shakib@bscse.uiu.ac.bd','UIU-2021-078',NULL,175.00,20.00,195.00,'cash_on_delivery','pending','delivery','pending',NULL,'2026-08-25 11:15:00'),   (4,3,'012374640','Farhan Rahman','018xxxxxxx','Room 201, 3rd Floor, UIU','farhan@bscse.uiu.ac.bd','UIU-2022-045','Extra sauce please',50.00,18.00,68.00,'cash_on_delivery','pending','delivery','pending',NULL,'2026-08-25 11:30:00');  -- Sample Order Items INSERT INTO `order_items` (`order_id`,`food_id`,`food_name`,`stall_name`,`quantity`,`unit_price`,`total_price`) VALUES   (1,1,'Burger',"Khan's Kitchen",2,50.00,100.00),   (1,2,'Chicken Roll',"Khan's Kitchen",1,35.00,35.00),   (1,28,'Regular Coffee','Brew Cafe',2,20.00,40.00),   (2,1,'Burger',"Khan's Kitchen",2,50.00,100.00),   (2,2,'Chicken Roll',"Khan's Kitchen",1,35.00,35.00),   (2,28,'Regular Coffee','Brew Cafe',2,20.00,40.00),   (3,1,'Burger',"Khan's Kitchen",2,50.00,100.00),   (3,2,'Chicken Roll',"Khan's Kitchen",1,35.00,35.00),   (3,28,'Regular Coffee','Brew Cafe',2,20.00,40.00),   (4,1,'BBQ Chicken Burger',"Khan's Kitchen",1,50.00,50.00);  -- Sample Deliveries  (nullable dates now use DATETIME → no error) INSERT INTO `deliveries` (`order_id`,`rider_id`,`status`,`delivery_fee`,`rider_earn`,`accepted_at`,`picked_up_at`,`delivered_at`) VALUES   (1,2,'delivered',20.00,12.00,'2026-08-25 10:47:00','2026-08-25 10:55:00','2026-08-25 11:05:00'),   (2,2,'delivered',20.00,12.00,'2026-08-25 11:02:00','2026-08-25 11:10:00','2026-08-25 11:20:00'),   (3,NULL,'pending',20.00,12.00,NULL,NULL,NULL),   (4,NULL,'pending',18.00,12.00,NULL,NULL,NULL);  -- Sample Payments INSERT INTO `payments` (`order_id`,`user_id`,`method`,`amount`,`currency`,`status`,`paid_at`) VALUES   (1,3,'cash_on_delivery',195.00,'BDT','paid','2026-08-25 11:05:00'),   (2,3,'cash_on_delivery',195.00,'BDT','paid','2026-08-25 11:20:00'),   (3,3,'cash_on_delivery',195.00,'BDT','pending',NULL),   (4,3,'cash_on_delivery',68.00,'BDT','pending',NULL);  -- Sample Reviews INSERT INTO `reviews` (`user_id`,`food_id`,`order_id`,`stall_id`,`rating`,`review`,`is_visible`) VALUES   (3,1,1,1,5,'Best burger on campus! Delivered hot and fresh.',1),   (4,27,NULL,4,5,'Crispy Chicken from CP is amazing!',1),   (5,32,NULL,5,5,'Latte Coffee is perfect. Best on campus!',1);  -- Sample Rider Ratings INSERT INTO `rider_ratings` (`delivery_id`,`rider_id`,`customer_id`,`rating`,`comment`) VALUES   (1,2,3,5,'Very fast and polite. Food arrived in perfect condition!'),   (2,2,3,4,'Good delivery, slightly late but professional.');  -- Sample Notifications INSERT INTO `notifications` (`user_id`,`title`,`message`,`type`,`is_read`) VALUES   (3,'Order Confirmed!','Your order #012374639 has been confirmed and is being prepared.','order_confirmed',0),   (3,'Order Delivered!','Your order #012374637 has been delivered. Enjoy your meal!','order_delivered',1),   (2,'New Delivery Request','A new delivery request is available near Khan\'s Kitchen.','announcement',0),   (2,'Earnings Updated!','You earned BDT 12 for delivering order #012374637.','announcement',1),   (NULL,'New Stall Opening!','Campus Bites is now available on UniBites. Check it out!','new_stall',0),   (NULL,'Special Food Today!','Brew Cafe is offering 20% off on all coffees today!','special_food',0);  -- Sample Favorites INSERT INTO `favorites` (`user_id`,`food_id`,`stall_id`) VALUES   (3,1,NULL),(3,NULL,5),(4,27,NULL),(5,NULL,1);  -- Sample Contact Messages INSERT INTO `contact_messages` (`name`,`phone`,`email`,`message`,`is_read`) VALUES   ('Farhan Rahman','018xxxxxxx','farhan@bscse.uiu.ac.bd','My order was delayed. Please improve delivery time.',0),   ('Nadia Islam','015xxxxxxx','nadia@bscse.uiu.ac.bd','How do I become a rider?',1),   ('Shakil Ahmed','019xxxxxxx','shakil@bscse.uiu.ac.bd','Can you add Dhaba stall to UniBites?',0);   -- ============================================================ --  VIEWS -- ============================================================  CREATE OR REPLACE VIEW `view_pending_deliveries` AS SELECT   o.id              AS order_id,   o.order_number,   o.full_name       AS customer_name,   o.phone           AS customer_phone,   o.location        AS drop_off_location,   o.subtotal,   d.delivery_fee,   o.total,   d.rider_earn,   o.created_at      AS order_time,   GROUP_CONCAT(CONCAT(oi.quantity,'x ',oi.food_name,' (',oi.stall_name,')') SEPARATOR ' | ') AS items_summary FROM `orders` o JOIN `deliveries`  d  ON d.order_id = o.id JOIN `order_items` oi ON oi.order_id = o.id WHERE d.status = 'pending'   AND o.status IN ('ready','delivery_requested') GROUP BY o.id;  CREATE OR REPLACE VIEW `view_rider_earnings` AS SELECT   u.id              AS rider_id,   CONCAT(u.first_name,' ',u.last_name) AS rider_name,   u.university_id,   u.department,   COUNT(d.id)       AS total_deliveries,   SUM(d.rider_earn) AS total_earned,   SUM(CASE WHEN DATE(d.delivered_at)=CURDATE() THEN d.rider_earn ELSE 0 END) AS today_earned,   COALESCE(AVG(rr.rating),0) AS avg_rating FROM `users` u JOIN `deliveries` d ON d.rider_id = u.id AND d.status = 'delivered' LEFT JOIN `rider_ratings` rr ON rr.rider_id = u.id WHERE u.is_rider = 1 GROUP BY u.id;  CREATE OR REPLACE VIEW `view_admin_dashboard` AS SELECT   (SELECT COUNT(*) FROM users WHERE role='user')                                               AS total_users,   (SELECT COUNT(*) FROM stalls WHERE is_active=1)                                              AS total_stalls,   (SELECT COUNT(*) FROM foods  WHERE is_available=1)                                           AS total_foods,   (SELECT COUNT(*) FROM orders WHERE DATE(created_at)=CURDATE())                               AS todays_orders,   (SELECT COUNT(*) FROM orders WHERE status='pending')                                         AS pending_orders,   (SELECT COUNT(*) FROM deliveries WHERE status IN ('accepted','picked_up','out_for_delivery')) AS active_deliveries,   (SELECT COUNT(*) FROM orders WHERE status IN ('completed','delivered'))                       AS completed_orders,   (SELECT COALESCE(SUM(total),0) FROM orders WHERE payment_status='paid')                      AS total_revenue,   (SELECT COUNT(DISTINCT rider_id) FROM deliveries WHERE status IN ('accepted','picked_up','out_for_delivery')) AS active_riders;  CREATE OR REPLACE VIEW `view_order_details` AS SELECT   o.id,   o.order_number,   o.created_at,   CONCAT(u.first_name,' ',u.last_name) AS customer_name,   u.email                              AS customer_email,   o.phone,   o.location                           AS delivery_location,   o.student_id,   o.subtotal,   o.delivery_fee,   o.total,   o.payment_method,   o.payment_status,   o.delivery_type,   o.status                             AS order_status,   CONCAT(r.first_name,' ',r.last_name) AS rider_name,   d.status                             AS delivery_status,   d.accepted_at,   d.delivered_at FROM `orders` o JOIN `users`       u ON u.id = o.user_id LEFT JOIN `users`  r ON r.id = o.rider_id LEFT JOIN `deliveries` d ON d.order_id = o.id;   -- ============================================================ --  STORED PROCEDURES -- ============================================================  DELIMITER $$  CREATE PROCEDURE `sp_place_order` (   IN  p_user_id        INT,   IN  p_full_name      VARCHAR(100),   IN  p_phone          VARCHAR(20),   IN  p_location       TEXT,   IN  p_email          VARCHAR(100),   IN  p_student_id     VARCHAR(30),   IN  p_notes          TEXT,   IN  p_payment_method ENUM('cash_on_delivery','online'),   IN  p_delivery_type  ENUM('pickup','delivery'),   IN  p_subtotal       DECIMAL(10,2),   IN  p_delivery_fee   DECIMAL(10,2),   OUT p_order_id       INT,   OUT p_order_number   VARCHAR(20) ) BEGIN   SET p_order_number = CONCAT('0', FLOOR(RAND() * 9000000000 + 1000000000));    INSERT INTO `orders` (     user_id,order_number,full_name,phone,location,     email,student_id,notes,subtotal,delivery_fee,total,     payment_method,delivery_type,status   ) VALUES (     p_user_id,p_order_number,p_full_name,p_phone,p_location,     p_email,p_student_id,p_notes,p_subtotal,p_delivery_fee,     (p_subtotal + p_delivery_fee),p_payment_method,p_delivery_type,'pending'   );    SET p_order_id = LAST_INSERT_ID();    IF p_delivery_type = 'delivery' THEN     INSERT INTO `deliveries` (order_id,delivery_fee,rider_earn)     VALUES (p_order_id, p_delivery_fee, (p_delivery_fee * 0.6));   END IF;    INSERT INTO `payments` (order_id,user_id,method,amount,currency,status)   VALUES (p_order_id,p_user_id,p_payment_method,(p_subtotal+p_delivery_fee),'BDT','pending');    INSERT INTO `notifications` (user_id,title,message,type)   VALUES (p_user_id,     CONCAT('Order #',p_order_number,' Placed!'),     CONCAT('Your order has been placed. Total: BDT ',(p_subtotal+p_delivery_fee)),     'order_confirmed'); END$$  CREATE PROCEDURE `sp_accept_delivery` (   IN  p_rider_id  INT,   IN  p_order_id  INT,   OUT p_success   TINYINT,   OUT p_message   VARCHAR(200) ) BEGIN   DECLARE v_current_rider INT DEFAULT NULL;   DECLARE v_status        VARCHAR(30);    SELECT rider_id, status INTO v_current_rider, v_status   FROM `deliveries`   WHERE order_id = p_order_id   FOR UPDATE;    IF v_current_rider IS NOT NULL THEN     SET p_success = 0;     SET p_message = 'Already accepted by another rider.';   ELSEIF v_status != 'pending' THEN     SET p_success = 0;     SET p_message = CONCAT('Status is: ', v_status, '. Cannot accept.');   ELSE     UPDATE `deliveries`     SET rider_id = p_rider_id, status = 'accepted', accepted_at = NOW()     WHERE order_id = p_order_id;      UPDATE `orders`     SET rider_id = p_rider_id, status = 'rider_accepted'     WHERE id = p_order_id;      INSERT INTO `notifications` (user_id,title,message,type)     SELECT user_id,       'Rider Accepted Your Order!',       CONCAT('A rider accepted delivery for order #',order_number,'. Food is on the way!'),       'rider_accepted'     FROM `orders` WHERE id = p_order_id;      SET p_success = 1;     SET p_message = 'Delivery accepted successfully.';   END IF; END$$  CREATE PROCEDURE `sp_update_order_status` (   IN p_order_id INT,   IN p_status   VARCHAR(30),   IN p_admin_id INT ) BEGIN   UPDATE `orders` SET status = p_status WHERE id = p_order_id;    INSERT INTO `admin_logs` (admin_id,action,table_name,record_id,new_value)   VALUES (p_admin_id,CONCAT('Updated order status to: ',p_status),'orders',p_order_id,p_status);    INSERT INTO `notifications` (user_id,title,message,type)   SELECT user_id,     CONCAT('Order Update: ',p_status),     CONCAT('Your order #',order_number,' status: ',p_status),     'order_confirmed'   FROM `orders` WHERE id = p_order_id; END$$  CREATE PROCEDURE `sp_complete_delivery` (   IN p_delivery_id INT,   IN p_order_id    INT ) BEGIN   DECLARE v_rider_id   INT;   DECLARE v_rider_earn DECIMAL(10,2);    SELECT rider_id, rider_earn INTO v_rider_id, v_rider_earn   FROM `deliveries` WHERE id = p_delivery_id;    UPDATE `deliveries`   SET status = 'delivered', delivered_at = NOW()   WHERE id = p_delivery_id;    UPDATE `orders`   SET status = 'delivered', payment_status = 'paid'   WHERE id = p_order_id;    UPDATE `users`   SET total_earnings = total_earnings + v_rider_earn,       balance        = balance + v_rider_earn   WHERE id = v_rider_id;    INSERT INTO `notifications` (user_id,title,message,type)   VALUES (v_rider_id,     'Delivery Completed — Earnings Credited!',     CONCAT('You earned BDT ',v_rider_earn,' for order #',p_order_id,'.'),     'announcement'); END$$  DELIMITER ;  -- Extra indexes CREATE INDEX idx_foods_price   ON `foods`    (`price`); CREATE INDEX idx_orders_date   ON `orders`   (`created_at`); CREATE INDEX idx_payments_date ON `payments` (`created_at`);  COMMIT;  -- ============================================================ --  DEFAULT CREDENTIALS --  Admin : admin@unibites.com    / Test@1234 --  User  : user@bscse.uiu.ac.bd / Test@1234 -- --  Import: phpMyAdmin → Import → select this file → Go --  CLI   : mysql -u root -p < unibites_fixed.sql -- ============================================================
